export const validateLibrary = (library) => {
  if (!library) {
    throw new Error('Library is required');
  }
  if (typeof library !== 'object') {
    throw new Error('Library must be an object');
  }
  if (!library.name) {
    throw new Error('Library must have a name');
  }
  if (!library.version) {
    throw new Error('Library must have a version');
  }
  return true;
};

import { strict as assert } from 'assert';
import { validateLibrary } from '../src/library_validation_contract.mjs';

describe('Library Validation Contract', () => {
  it('should validate a valid library', () => {
    const library = {
      name: 'example-library',
      version: '1.0.0'
    };
    assert.strictEqual(validateLibrary(library), true);
  });

  it('should throw an error if library is null', () => {
    assert.throws(() => validateLibrary(null), /Library is required/);
  });

  it('should throw an error if library is not an object', () => {
    assert.throws(() => validateLibrary('not an object'), /Library must be an object/);
  });

  it('should throw an error if library has no name', () => {
    const library = {
      version: '1.0.0'
    };
    assert.throws(() => validateLibrary(library), /Library must have a name/);
  });

  it('should throw an error if library has no version', () => {
    const library = {
      name: 'example-library'
    };
    assert.throws(() => validateLibrary(library), /Library must have a version/);
  });
});

